#include <gtest/gtest.h>

#include "cart.h"

TEST(CartTest, StartsEmpty) {
  Inventory inventory;
  inventory.add("apple", 3);
  Cart cart(inventory);
  EXPECT_TRUE(cart.empty());
}

TEST(CartTest, AddsItem) {
  Inventory inventory;
  inventory.add("apple", 3);
  Cart cart(inventory);
  cart.add("apple", 1);
  EXPECT_EQ(cart.count("apple"), 1);
}

TEST(CartTest, RejectsOverStock) {
  Inventory inventory;
  inventory.add("apple", 3);
  Cart cart(inventory);
  EXPECT_FALSE(cart.add("apple", 4));
}

